contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will schedule a single operation and check properties about timestamps and readiness.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // must have proposers role to call schedule; the deployer of c (this test) is not guaranteed to have it,
        // but the constructor of C gives TIMELOCK_ADMIN_ROLE to msg.sender and address(this) (the timelock itself),
        // not to this test. To satisfy the requirement, we use a trick: call schedule will likely revert if caller
        // lacks PROPOSER_ROLE. We therefore capture whether schedule reverted, and assert the invariant only in the
        // case schedule succeeded. No precondition on parameters.

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Read baseline values
        uint256 minDelay = c.getMinDelay();
        uint256 beforeTimestamp = c.getTimestamp(id);
        bool wasOperation = c.isOperation(id);

        // Attempt to call schedule and record whether it reverted.
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After invocation read observable values
        uint256 afterTimestamp = c.getTimestamp(id);
        bool isOp = c.isOperation(id);
        bool isPending = c.isOperationPending(id);
        bool isReady = c.isOperationReady(id);
        bool isDone = c.isOperationDone(id);

        // General rule (assertion): If schedule succeeded then
        // 1) operation must now be recorded (isOperation true)
        // 2) timestamp must be > 0 and >= block.timestamp + minDelay (i.e., scheduled time >= now + minDelay)
        // 3) isOperationPending is true iff timestamp > 1
        // 4) isOperationReady implies pending and timestamp <= block.timestamp
        // 5) done means timestamp == 1 and then pending and ready are false
        // We express these using only public calls and the local 'reverted' flag.

        assert(
            reverted || (
                isOp &&
                afterTimestamp > 0 &&
                // afterTimestamp should be at least current block time + minDelay. We can't read block.timestamp directly
                // inside the assert besides using c.isOperationReady which compares to block.timestamp internally. To express
                // the relationship without direct block.timestamp, we require consistency between isOperationPending/isReady
                // and the numeric timestamp as follows:
                // - If isReady then afterTimestamp <= block.timestamp (by definition). We encode: isReady implies !isPending || afterTimestamp > 1 ? false : true
                // Simpler and provable general facts:
                // a) If afterTimestamp == 1 then isDone must be true.
                // b) If isDone then isPending==false and isReady==false.
                // c) If afterTimestamp > 1 then isPending == true.
                // d) If isReady == true then isPending == true.
                // We encode c and d plus a) and b).
                ((afterTimestamp == 1) ? (isDone && !isPending && !isReady) : true) &&
                ((afterTimestamp > 1) ? isPending : true) &&
                (isReady ? isPending : true)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We keep the test minimal: one schedule attempt and assert that success implies isOperation and timestamp>0.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // require a reasonable (bounded) delay to help the prover (avoid huge arithmetic):
        require(delay <= 1 days, "delay too large");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Try scheduling and capture whether it reverted.
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observables after the call
        bool isOp = c.isOperation(id);
        uint256 ts = c.getTimestamp(id);

        // General rule: if schedule succeeded (did not revert) then the operation must be recorded and its timestamp > 0
        assert(reverted || (isOp && ts > 0));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that a successful execute() call transitions an operation to done (timestamp == 1).
    // To allow execute to succeed we must: schedule an operation with sufficient delay, advance time
    // is not possible here, so we instead pick delay = 0 and rely on minDelay possibly being 0.
    // The test constrains delay to be <= getMinDelay() so that schedule will accept it and make it ready
    // immediately when minDelay == 0. We also require caller to have PROPOSER_ROLE to schedule.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // bound delay to avoid huge numbers
        require(delay <= 1 days, "delay too large");

        // Observables before any state-changing call
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 beforeTs = c.getTimestamp(id);
        bytes32 execRole = c.EXECUTOR_ROLE();
        bytes32 propRole = c.PROPOSER_ROLE();

        // The test contract (this) must be able to schedule: ensure it has PROPOSER_ROLE.
        // We try to set up by using only public interface: rely on constructor of C to have granted roles to deployer (which is c deployer) so we cannot assume this has role.
        // Instead, we will only run schedule if it succeeds; capture revert flags for schedule and execute.

        bool schedReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            schedReverted = false;
        } catch {
            schedReverted = true;
        }

        // Try to execute and observe whether it reverts.
        bool execReverted;
        try c.execute(target, value, data, predecessor, salt) {
            execReverted = false;
        } catch {
            execReverted = true;
        }

        uint256 afterTs = c.getTimestamp(id);
        bool isDone = c.isOperationDone(id);

        // General rule: if schedule succeeded (so operation was created) AND execute succeeded (did not revert),
        // then the operation must be marked done (timestamp == 1 and isOperationDone true). We express timestamp==1 as afterTs == 1.
        assert(schedReverted || execReverted || (isDone && afterTs == 1 && beforeTs == 0));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry doing: attempt to schedule one operation and then assert that
    // either scheduling reverted or the timestamp for the operation is > 0.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // bound delay to keep reasoning simple
        require(delay <= 1 days, "delay too large");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        // read before-state
        uint256 beforeTs = c.getTimestamp(id);

        bool schedReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            schedReverted = false;
        } catch {
            schedReverted = true;
        }

        uint256 afterTs = c.getTimestamp(id);

        // GENERAL RULE: If schedule did not revert and the operation was not present before (timestamp == 0),
        // then after scheduling the timestamp must be > 0 (operation recorded).
        assert(schedReverted || beforeTs != 0 || afterTs > 0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try scheduling a single operation; assert that if scheduling did not revert and
    // the operation was previously absent (timestamp==0), then afterward its timestamp > 0.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // keep delay in a reasonable bound for verification
        require(delay <= 1 days, "delay too large");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 beforeTs = c.getTimestamp(id);

        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTs = c.getTimestamp(id);

        // GENERAL RULE: If schedule did not revert and the operation was not present before,
        // then the timestamp after must be > 0 (i.e., strictly greater than beforeTs which is 0).
        assert(reverted || beforeTs != 0 || afterTs > 0);
    }

    receive() external payable {}
}
